def change_cabin(reservation_id: str, cabin: str, payment_id: str):
    """
    Change ONLY the cabin class of a reservation, keeping every existing flight unchanged.

    Use this for requests like "upgrade to business" or "downgrade all passengers to basic
    economy" when the FLIGHTS themselves are NOT changing. It automatically re-uses all the
    reservation's current flight segments, so you never have to re-list them (a common
    mistake that drops segments). To ALSO change which flights are on the reservation, use
    `update_reservation_flights` instead.

    The returned reservation has an added `payment_summary` field with the EXACT amount
    charged (upgrade) or refunded (downgrade). Report THAT number to the user verbatim; do
    not compute it yourself.

    Policy notes:
      - Cabin class applies to the WHOLE reservation; you cannot change cabin for one segment.
      - Cabin cannot be changed if any flight in the reservation has already been flown.

    Args:
        reservation_id: The reservation ID, a 6-character code such as 'M20IZO'.
        cabin: The new cabin for the whole reservation. Exactly one of:
            'basic_economy', 'economy', 'business'.
        payment_id: A SINGLE gift card or credit card id already in the user's profile,
            such as 'credit_card_9074831'. A certificate CANNOT be used.

    Returns:
        The updated reservation with a `payment_summary` field, or an error message string.
    """
    res = env_get_reservation_details(reservation_id=reservation_id)
    if not isinstance(res, dict):
        return res

    # Policy: cabin cannot be changed if any flight has already been flown.
    # Current policy date is 2024-05-15; treat a strictly-earlier flight date as flown.
    try:
        for fl in (res.get("flights") or []):
            dt = str(fl.get("date") or "")
            if dt and dt < "2024-05-15":
                return (
                    f"Cannot change cabin: flight {fl.get('flight_number')} on {dt} has "
                    "already been flown. Cabin cannot be changed once any flight in the "
                    "reservation has been flown; transfer to a human agent if needed."
                )
    except Exception:
        pass

    flights = [
        {"flight_number": fl.get("flight_number"), "date": fl.get("date")}
        for fl in (res.get("flights") or [])
    ]

    def _flight_total(r):
        try:
            npax = len(r.get("passengers") or [])
            return sum(int(fl.get("price", 0)) for fl in (r.get("flights") or [])) * npax
        except Exception:
            return None

    old_total = _flight_total(res)

    result = env_update_reservation_flights(
        reservation_id=reservation_id, cabin=cabin, flights=flights, payment_id=payment_id
    )

    if isinstance(result, dict) and old_total is not None:
        new_total = _flight_total(result)
        if new_total is not None:
            delta = new_total - old_total
            if delta > 0:
                result["payment_summary"] = f"Charged ${delta} to {payment_id} for this cabin change."
            elif delta < 0:
                result["payment_summary"] = f"Refunded ${-delta} to {payment_id} for this cabin change."
            else:
                result["payment_summary"] = "No additional charge or refund for this cabin change."
    return result
